-- Tighten direct table writes: posting RPCs are the only route for stock/invoice/purchase mutation.
drop policy if exists krushna_products_member_all on public.krushna_products;
create policy krushna_products_read on public.krushna_products for select using(public.krushna_is_member(business_id));
create policy krushna_products_insert on public.krushna_products for insert with check(public.krushna_has_role(business_id,array['owner','admin','manager']));
create policy krushna_products_update on public.krushna_products for update using(public.krushna_has_role(business_id,array['owner','admin','manager'])) with check(public.krushna_has_role(business_id,array['owner','admin','manager']));
create policy krushna_products_delete on public.krushna_products for delete using(public.krushna_has_role(business_id,array['owner','admin']));
drop policy if exists krushna_parties_member_all on public.krushna_parties;
create policy krushna_parties_read on public.krushna_parties for select using(public.krushna_is_member(business_id));
create policy krushna_parties_insert on public.krushna_parties for insert with check(public.krushna_has_role(business_id,array['owner','admin','manager','cashier']));
create policy krushna_parties_update on public.krushna_parties for update using(public.krushna_has_role(business_id,array['owner','admin','manager','cashier'])) with check(public.krushna_has_role(business_id,array['owner','admin','manager','cashier']));
create policy krushna_parties_delete on public.krushna_parties for delete using(public.krushna_has_role(business_id,array['owner','admin']));
drop policy if exists krushna_itc_records_member_all on public.krushna_itc_records;
create policy krushna_itc_records_read on public.krushna_itc_records for select using(public.krushna_is_member(business_id));
create policy krushna_itc_records_insert on public.krushna_itc_records for insert with check(public.krushna_has_role(business_id,array['owner','admin','accountant']));
create policy krushna_itc_records_update on public.krushna_itc_records for update using(public.krushna_has_role(business_id,array['owner','admin','accountant'])) with check(public.krushna_has_role(business_id,array['owner','admin','accountant']));
create policy krushna_itc_records_delete on public.krushna_itc_records for delete using(public.krushna_has_role(business_id,array['owner','admin']));
drop policy if exists krushna_tds_records_member_all on public.krushna_tds_records;
create policy krushna_tds_records_read on public.krushna_tds_records for select using(public.krushna_is_member(business_id));
create policy krushna_tds_records_insert on public.krushna_tds_records for insert with check(public.krushna_has_role(business_id,array['owner','admin','accountant']));
create policy krushna_tds_records_update on public.krushna_tds_records for update using(public.krushna_has_role(business_id,array['owner','admin','accountant'])) with check(public.krushna_has_role(business_id,array['owner','admin','accountant']));
create policy krushna_tds_records_delete on public.krushna_tds_records for delete using(public.krushna_has_role(business_id,array['owner','admin']));
drop policy if exists krushna_invoice_sequences_member_all on public.krushna_invoice_sequences;
create policy krushna_invoice_sequences_read on public.krushna_invoice_sequences for select using(public.krushna_is_member(business_id));
drop policy if exists krushna_invoices_member_all on public.krushna_invoices;
create policy krushna_invoices_read on public.krushna_invoices for select using(public.krushna_is_member(business_id));
drop policy if exists krushna_purchases_member_all on public.krushna_purchases;
create policy krushna_purchases_read on public.krushna_purchases for select using(public.krushna_is_member(business_id));
drop policy if exists krushna_stock_movements_member_all on public.krushna_stock_movements;
create policy krushna_stock_movements_read on public.krushna_stock_movements for select using(public.krushna_is_member(business_id));
drop policy if exists krushna_audit_log_member_all on public.krushna_audit_log;
create policy krushna_audit_log_read on public.krushna_audit_log for select using(public.krushna_is_member(business_id));
drop policy if exists kr_invoice_lines_access on public.krushna_invoice_lines;
create policy kr_invoice_lines_read on public.krushna_invoice_lines for select using(exists(select 1 from public.krushna_invoices i where i.id=invoice_id and public.krushna_is_member(i.business_id)));
drop policy if exists kr_purchase_lines_access on public.krushna_purchase_lines;
create policy kr_purchase_lines_read on public.krushna_purchase_lines for select using(exists(select 1 from public.krushna_purchases p where p.id=purchase_id and public.krushna_is_member(p.business_id)));
